package energy;/** * EU能量显示工具类 * <p> * 提供统一的EU能量格式化显示方法，用于UI、tooltip和调试输出。 * 所有能量显示默认使用EU单位。 * </p> */public class EUEnergyDisplay {    /**     * 格式化能量显示（简短格式）     * 用于tooltip和简单UI显示     *     * @param stored 当前存储能量     * @param capacity 最大容量     * @return 格式化字符串，如 "512/1000 EU"     */    public static String formatEnergy(long stored, long capacity) {        return String.format("%d/%d EU", stored, capacity);    }    /**     * 格式化能量显示（详细格式）     * 用于高级UI和调试     *     * @param stored 当前存储能量     * @param capacity 最大容量     * @param voltage 电压等级     * @param transferRate 传输速率     * @return 格式化字符串，如 "512/1000 EU (LV, 32 EU/t)"     */    public static String formatDetailed(long stored, long capacity, EUVoltage voltage, long transferRate) {        return String.format("%d/%d EU (%s, %d EU/t)", stored, capacity, voltage.getName(), transferRate);    }    /**     * 格式化能量百分比     *     * @param stored 当前存储能量     * @param capacity 最大容量     * @return 百分比字符串，如 "51%"     */    public static String formatPercentage(long stored, long capacity) {        if (capacity <= 0) return "0%";        int percent = (int) ((stored * 100) / capacity);        return String.format("%d%%", percent);    }    /**     * 格式化能量速率     *     * @param rate 能量速率 (EU/t)     * @return 格式化字符串，如 "32 EU/t"     */    public static String formatRate(long rate) {        return String.format("%d EU/t", rate);    }    /**     * 格式化电压等级信息     *     * @param voltage 电压等级     * @return 格式化字符串，如 "LV (32 EU/t max)"     */    public static String formatVoltage(EUVoltage voltage) {        return String.format("%s (%d EU/t max)", voltage.getName(), voltage.getMaxVoltage());    }    /**     * 格式化发电机状态     *     * @param stored 当前存储能量     * @param capacity 最大容量     * @param generationRate 发电速率     * @param voltage 电压等级     * @return 多行格式化字符串     */    public static String formatGeneratorStatus(long stored, long capacity, long generationRate, EUVoltage voltage) {        StringBuilder sb = new StringBuilder();        sb.append(formatEnergy(stored, capacity)).append("\n");        sb.append("发电: ").append(formatRate(generationRate)).append("\n");        sb.append("电压: ").append(formatVoltage(voltage));        return sb.toString();    }    /**     * 从EUCapability获取显示字符串     *     * @param capability EU能力实例     * @return 格式化的能量显示     */    public static String fromCapability(EUCapability capability) {        if (capability == null) return "0/0 EU";        return capability.getEnergyDisplay();    }    /**     * 从EUCapability获取详细显示字符串     *     * @param capability EU能力实例     * @return 详细格式化的能量显示     */    public static String detailedFromCapability(EUCapability capability) {        if (capability == null) return "0/0 EU (Unknown, 0 EU/t)";        return capability.getDetailedInfo();    }    /**     * 格式化大数值能量（使用K/M/G单位）     *     * @param energy 能量值     * @return 格式化字符串，如 "1.5K EU" 或 "32M EU"     */    public static String formatLargeEnergy(long energy) {        if (energy >= 1_000_000_000) {            return String.format("%.1fG EU", energy / 1_000_000_000.0);        } else if (energy >= 1_000_000) {            return String.format("%.1fM EU", energy / 1_000_000.0);        } else if (energy >= 1_000) {            return String.format("%.1fK EU", energy / 1_000.0);        } else {            return String.format("%d EU", energy);        }    }    /**     * 格式化能量条（可视化进度）     *     * @param stored 当前存储能量     * @param capacity 最大容量     * @param length 条长度（字符数）     * @return 可视化能量条，如 "[████████░░] 80%"     */    public static String formatEnergyBar(long stored, long capacity, int length) {        if (capacity <= 0 || length <= 0) {            return "[" + "░".repeat(Math.max(0, length)) + "] 0%";        }                int filled = (int) ((stored * length) / capacity);        filled = Math.min(filled, length);        filled = Math.max(filled, 0);                int empty = length - filled;        int percent = (int) ((stored * 100) / capacity);                StringBuilder bar = new StringBuilder();        bar.append("[");        bar.append("█".repeat(filled));        bar.append("░".repeat(empty));        bar.append("] ").append(percent).append("%");                return bar.toString();    }}